use std::{fs,collections::BTreeMap};fn main(){let s=fs::read_to_string("research/hec_inversecost631_20261116/run/cells.tsv").unwrap();let mut v:BTreeMap<String,Vec<u128>>=BTreeMap::new();let mut w=v.clone();for l in s.lines().skip(1){let a:Vec<_>=l.split('\t').collect();assert_eq!(a[2],"0");v.entry(a[1].into()).or_default().push(a[4].parse().unwrap());w.entry(a[1].into()).or_default().push(a[3].parse().unwrap());}assert_eq!(v.len(),2);for(a,x)in &mut v{x.sort();assert_eq!(x.len(),5);let y=w.get_mut(a).unwrap();y.sort();println!("ARM {a} median_ns={} min_ns={} max_ns={} process_median_ns={}",x[2],x[0],x[4],y[2]);}let r=v["ordered"][2]as f64/v["direct"][2]as f64;println!("DERIVED ordered_over_direct={r:.12} time_reduction_percent={:.9} tenfold_gate={}",100.*(1.-1./r),r>=10.);let mut svg=String::from("<svg xmlns='http://www.w3.org/2000/svg' width='900' height='270'><rect width='900' height='270' fill='white'/><g font-family='sans-serif' fill='#182536'><text x='30' y='35' font-size='22'>F631 inverse component: all 10 cells verified</text>");for(i,a)in["ordered","direct"].iter().enumerate(){let m=v[*a][2]as f64/1e9;let y=65+i*75;svg+=&format!("<text x='30' y='{}'>{a}</text><rect x='135' y='{y}' width='{}' height='38' fill='#327d91'/><text x='{}' y='{}'>{m:.6} s</text>",y+25,m*220.,145.+m*220.,y+25);}svg+=&format!("<text x='30' y='250'>Median ratio {r:.3}x; component only; 10x gate failed; no cold-path timing</text></g></svg>");fs::write("research/hec_inversecost631_20261116/COST.svg",svg).unwrap();}
